import { useMemo, useState } from "react";
import { FlatList, Pressable, Share, StyleSheet, Text, TextInput, View } from "react-native";
import { useRouter } from "expo-router";

import { ScreenContainer } from "@/components/screen-container";
import { StatusPill } from "@/components/hub/status-pill";
import { useColors } from "@/hooks/use-colors";
import { getBudgetSummary, useAgentHub, type CostEntry } from "@/lib/agent-hub";
import { filterRuntimeRecords, getRuntimeEventType, getRuntimeSeverity, getRuntimeStats, runtimeSavedFilters, type RuntimeEventType, type RuntimeFilter, type RuntimeSeverity, type RuntimeTimeRange } from "@/lib/runtime-monitor";
import { buildRedactedRuntimeExport, runtimeRetentionPolicy } from "@/lib/runtime-data-policy";
import { getOperationalHealth } from "@/lib/runtime-health";
import { useRuntimeRealtime, type RuntimeRealtimeState } from "@/lib/runtime-realtime";
import { getRuntimeConnectionPresentation } from "@/lib/runtime-realtime-protocol";
import { trpc } from "@/lib/trpc";
import { useConnectivity } from "@/lib/connectivity";

type ControlView = "cost" | "approvals" | "runtime";

type ApprovalInboxEntry = {
  approval: { id: number; projectId: number; requestedBy: string; title: string; detail: string; impact: string; level: "auto" | "review" | "approval"; status: "pending" | "approved" | "rejected" | "auto_resolved" };
  project: { id: number; name: string; code: string };
  engineStep: { id: number; stepOrder: number; title: string } | null;
  engineRun: { id: number; status: "queued" | "running" | "awaiting_review" | "awaiting_approval" | "verifying" | "completed" | "failed" | "blocked" } | null;
  sensitiveChange: { id: number; path: string; riskSummary: string; status: "pending_secondary" | "applied" | "rejected" | "conflicted"; baseVersion: number } | null;
};

type RuntimeLogEntry = {
  request: { id: number; targetPath: string; status: string; profile: string; reason: string; exitCode: number | null; stdout: string | null; stderr: string | null; durationMs: number | null; createdAt: Date; completedAt: Date | null };
  project: { id: number; name: string; code: string };
  runner: { id: number | null; label: string | null; runnerKey: string | null } | null;
};

type RunnerEntry = { id: number; label: string; status: string; lastHeartbeatAt: Date | null };

export default function ControlScreen() {
  const router = useRouter();
  const colors = useColors();
  const { canPerformSensitiveActions } = useConnectivity();
  const [view, setView] = useState<ControlView>("cost");
  const [runtimeFilter, setRuntimeFilter] = useState<RuntimeFilter>("all");
  const [runtimeEventType, setRuntimeEventType] = useState<RuntimeEventType>("all");
  const [runtimeSeverity, setRuntimeSeverity] = useState<RuntimeSeverity>("all");
  const [runtimeSearch, setRuntimeSearch] = useState("");
  const [runtimeTimeRange, setRuntimeTimeRange] = useState<RuntimeTimeRange>("all");
  const [digestNotice, setDigestNotice] = useState("");
  const { costEntries, budgetLimit } = useAgentHub();
  const approvalsQuery = trpc.approvals.inbox.useQuery(undefined, { refetchInterval: 8_000 });
  const runtimeQuery = trpc.isolatedRuntime.listForOwner.useQuery(undefined, { refetchInterval: 8_000 });
  const runnersQuery = trpc.localRunners.list.useQuery(undefined, { refetchInterval: 8_000 });
  const operationalHealthQuery = trpc.operationalHealth.get.useQuery(undefined, { refetchInterval: 8_000 });
  const realtimeState = useRuntimeRealtime(view === "runtime" || view === "approvals");
  const utils = trpc.useUtils();
  const resolveApproval = trpc.approvals.resolve.useMutation({
    onSuccess: () => {
      utils.approvals.inbox.invalidate();
      utils.engine.listRuns.invalidate();
      utils.projects.list.invalidate();
      utils.isolatedRuntime.listForOwner.invalidate();
    },
  });
  const sendOwnerDigest = trpc.operationalHealth.sendOwnerDigest.useMutation({
    onSuccess: (result) => setDigestNotice(result.delivered ? "أُرسل ملخص التشغيل المنقح إلى المالك." : "تم إنشاء الملخص، لكن تعذر تسليمه الآن؛ أعد المحاولة لاحقاً."),
  });

  const approvals = approvalsQuery.data ?? [];
  const runtimeRequests = useMemo(() => (runtimeQuery.data ?? []) as RuntimeLogEntry[], [runtimeQuery.data]);
  const runners = useMemo(() => (runnersQuery.data ?? []) as RunnerEntry[], [runnersQuery.data]);
  const pendingApprovals = approvals.filter((item) => item.approval.status === "pending");
  const budget = useMemo(() => getBudgetSummary(costEntries, budgetLimit), [costEntries, budgetLimit]);
  const runtimeStats = useMemo(() => getRuntimeStats(runtimeRequests, pendingApprovals.length, runners.map((runner) => runner.status)), [runtimeRequests, pendingApprovals.length, runners]);
  const operationalHealth = useMemo(() => getOperationalHealth(operationalHealthQuery.data ?? { queued: 0, activeLeases: 0, failedLast24h: 0, pendingApprovals: 0, readyRunners: 0, workerStatus: "unknown", workerHeartbeatAt: null, budgetPercent: 0 }), [operationalHealthQuery.data]);
  const runtimeLogFilters = useMemo(() => ({ status: runtimeFilter, eventType: runtimeEventType, severity: runtimeSeverity, search: runtimeSearch, timeRange: runtimeTimeRange }), [runtimeEventType, runtimeFilter, runtimeSearch, runtimeSeverity, runtimeTimeRange]);
  const filteredRuntimeRequests = useMemo(() => filterRuntimeRecords(runtimeRequests, runtimeLogFilters), [runtimeLogFilters, runtimeRequests]);
  const applyRuntimePreset = (preset: typeof runtimeSavedFilters[number]) => { setRuntimeFilter(preset.status); setRuntimeEventType(preset.eventType); setRuntimeSeverity(preset.severity); setRuntimeSearch(preset.search ?? ""); setRuntimeTimeRange(preset.timeRange ?? "all"); };
  const exportRuntime = async () => { await Share.share({ title: "سجل Runtime المنقح", message: buildRedactedRuntimeExport(filteredRuntimeRequests) }); };
  const header = <ControlHeader view={view} setView={setView} pendingCount={pendingApprovals.length} runtimeCount={runtimeRequests.length} budget={budget} budgetLimit={budgetLimit} colors={colors} />;

  if (view === "cost") {
    return <ScreenContainer className="px-5" containerClassName="bg-background"><FlatList<CostEntry> data={costEntries} keyExtractor={(item) => item.id} contentContainerStyle={styles.list} ListHeaderComponent={header} renderItem={({ item }) => <CostRow entry={item} colors={colors} />} ItemSeparatorComponent={Separator} ListFooterComponent={<Text style={[styles.localNote, { color: colors.muted }]}>هذه قيَم تشغيلية محلية للنسخة الأولى، وليست فاتورة أو خصماً خارجياً.</Text>} /></ScreenContainer>;
  }

  if (view === "approvals") {
    return <ScreenContainer className="px-5" containerClassName="bg-background"><FlatList<ApprovalInboxEntry> data={approvals} keyExtractor={(item) => String(item.approval.id)} contentContainerStyle={styles.list} ListHeaderComponent={header} renderItem={({ item }) => <ApprovalRow record={item} colors={colors} resolving={resolveApproval.isPending} canResolve={canPerformSensitiveActions} onResolve={(decision) => resolveApproval.mutate({ projectId: item.approval.projectId, approvalId: item.approval.id, decision })} />} ItemSeparatorComponent={Separator} ListEmptyComponent={<EmptyApprovals loading={approvalsQuery.isLoading} error={Boolean(approvalsQuery.error)} colors={colors} />} ListFooterComponent={<ApprovalFootnote colors={colors} />} /></ScreenContainer>;
  }

  return <ScreenContainer className="px-5" containerClassName="bg-background"><FlatList<RuntimeLogEntry> data={filteredRuntimeRequests} keyExtractor={(item) => String(item.request.id)} contentContainerStyle={styles.list} ListHeaderComponent={<><>{header}</>{digestNotice ? <Text accessibilityLiveRegion="polite" style={[styles.digestNotice, { backgroundColor: colors.subtle, borderColor: colors.border, color: colors.foreground }]}>{digestNotice}</Text> : null}<Pressable accessibilityRole="button" disabled={!canPerformSensitiveActions || sendOwnerDigest.isPending} onPress={() => sendOwnerDigest.mutate()} style={({ pressed }) => [styles.ownerDigestLink, { backgroundColor: colors.surface, borderColor: colors.primary }, (pressed || !canPerformSensitiveActions || sendOwnerDigest.isPending) && styles.disabled]}><Text style={[styles.runnerPairingLinkTitle, { color: colors.foreground }]}>{sendOwnerDigest.isPending ? "جارٍ إرسال الملخص…" : "إرسال ملخص التشغيل للمالك"}</Text><Text style={[styles.runnerPairingLinkCopy, { color: colors.muted }]}>ملخص منقح للحالة الحية؛ لا يشغّل أي تنفيذ ولا ينشئ جدولاً دورياً.</Text></Pressable><Pressable accessibilityRole="button" onPress={() => router.push("/runner-pairing")} style={({ pressed }) => [styles.runnerPairingLink, { backgroundColor: colors.subtle, borderColor: colors.primary }, pressed && styles.pressed]}><Text style={[styles.runnerPairingLinkTitle, { color: colors.foreground }]}>إقران Runner من الهاتف</Text><Text style={[styles.runnerPairingLinkCopy, { color: colors.muted }]}>أنشئ تهيئة آمنة لجهاز Docker لوقت لاحق؛ لا يبدأ تنفيذ من هذا الإجراء.</Text></Pressable><RuntimeDashboard runners={runners} stats={runtimeStats} operationalHealth={operationalHealth} pendingApprovals={pendingApprovals} filter={runtimeFilter} setFilter={setRuntimeFilter} eventType={runtimeEventType} setEventType={setRuntimeEventType} severity={runtimeSeverity} setSeverity={setRuntimeSeverity} search={runtimeSearch} setSearch={setRuntimeSearch} timeRange={runtimeTimeRange} setTimeRange={setRuntimeTimeRange} onApplyPreset={applyRuntimePreset} onExport={exportRuntime} onRefreshHealth={() => { void Promise.all([operationalHealthQuery.refetch(), runtimeQuery.refetch(), runnersQuery.refetch(), approvalsQuery.refetch()]); }} filteredCount={filteredRuntimeRequests.length} totalCount={runtimeRequests.length} realtimeState={realtimeState} colors={colors} resolving={resolveApproval.isPending} canResolve={canPerformSensitiveActions} onResolve={(record, decision) => resolveApproval.mutate({ projectId: record.approval.projectId, approvalId: record.approval.id, decision })} /></>} renderItem={({ item }) => <RuntimeRow record={item} colors={colors} />} ItemSeparatorComponent={Separator} ListEmptyComponent={<EmptyRuntime loading={runtimeQuery.isLoading} error={Boolean(runtimeQuery.error)} filters={runtimeLogFilters} colors={colors} />} ListFooterComponent={<RuntimeFootnote colors={colors} />} /></ScreenContainer>;
}

function Separator() { return <View style={styles.separator} />; }

function ControlHeader({ view, setView, pendingCount, runtimeCount, budget, budgetLimit, colors }: { view: ControlView; setView: (view: ControlView) => void; pendingCount: number; runtimeCount: number; budget: ReturnType<typeof getBudgetSummary>; budgetLimit: number; colors: ReturnType<typeof useColors> }) {
  return <View><Text style={[styles.eyebrow, { color: colors.primary }]}>حوكمة التنفيذ</Text><Text style={[styles.heading, { color: colors.foreground }]}>مركز التحكم</Text><Text style={[styles.subheading, { color: colors.muted }]}>راقب الاستهلاك، وافحص التنفيذ، واتخذ القرار المطلوب قبل أي إجراء مؤثر.</Text><View style={[styles.switcher, { backgroundColor: colors.subtle }]}><ControlTab active={view === "cost"} label="التكلفة" onPress={() => setView("cost")} colors={colors} /><ControlTab active={view === "approvals"} label={`الموافقات${pendingCount ? ` · ${pendingCount}` : ""}`} onPress={() => setView("approvals")} colors={colors} /><ControlTab active={view === "runtime"} label={`Runtime${runtimeCount ? ` · ${runtimeCount}` : ""}`} onPress={() => setView("runtime")} colors={colors} /></View>{view === "cost" ? <BudgetSummary spent={budget.spent} remaining={budget.remaining} percent={budget.percent} budgetLimit={budgetLimit} colors={colors} /> : view === "approvals" ? <ApprovalSummary pendingCount={pendingCount} colors={colors} /> : null}</View>;
}

function ControlTab({ active, label, onPress, colors }: { active: boolean; label: string; onPress: () => void; colors: ReturnType<typeof useColors> }) { return <Pressable onPress={onPress} style={({ pressed }) => [styles.switchButton, active && { backgroundColor: colors.elevated }, pressed && styles.pressed]}><Text style={[styles.switchText, { color: active ? colors.primary : colors.muted }]}>{label}</Text></Pressable>; }

function RuntimeDashboard({ runners, stats, operationalHealth, pendingApprovals, filter, setFilter, eventType, setEventType, severity, setSeverity, search, setSearch, timeRange, setTimeRange, onApplyPreset, onExport, onRefreshHealth, filteredCount, totalCount, realtimeState, colors, resolving, canResolve, onResolve }: { runners: RunnerEntry[]; stats: ReturnType<typeof getRuntimeStats>; operationalHealth: ReturnType<typeof getOperationalHealth>; pendingApprovals: ApprovalInboxEntry[]; filter: RuntimeFilter; setFilter: (filter: RuntimeFilter) => void; eventType: RuntimeEventType; setEventType: (eventType: RuntimeEventType) => void; severity: RuntimeSeverity; setSeverity: (severity: RuntimeSeverity) => void; search: string; setSearch: (value: string) => void; timeRange: RuntimeTimeRange; setTimeRange: (value: RuntimeTimeRange) => void; onApplyPreset: (preset: typeof runtimeSavedFilters[number]) => void; onExport: () => void; onRefreshHealth: () => void; filteredCount: number; totalCount: number; realtimeState: RuntimeRealtimeState; colors: ReturnType<typeof useColors>; resolving: boolean; canResolve: boolean; onResolve: (record: ApprovalInboxEntry, decision: "approved" | "rejected") => void }) {
  const primaryRunner = runners.find((runner) => runner.status === "ready") ?? runners[0];
  const runnerReady = primaryRunner?.status === "ready";
  const connectionInfo = getRuntimeConnectionPresentation(realtimeState);
  const connection = connectionInfo.tone === "live"
    ? { ...connectionInfo, background: "#143D2A", border: "#2A734D", dot: colors.success }
    : connectionInfo.tone === "reconnecting"
      ? { ...connectionInfo, background: "#432B18", border: "#765724", dot: colors.warning }
      : { ...connectionInfo, background: "#3B2D16", border: "#6D572C", dot: colors.warning };
  return <View><View style={[styles.runtimeHero, { backgroundColor: colors.surface, borderColor: runnerReady ? colors.success : colors.warning }]}><View style={styles.runtimeHeroTop}><View style={styles.runtimeHeroCopy}><Text style={[styles.runtimeEyebrow, { color: runnerReady ? colors.success : colors.warning }]}>نبض التنفيذ</Text><Text style={[styles.runtimeHeroTitle, { color: colors.foreground }]}>{runnerReady ? "Runner متصل وجاهز" : "التنفيذ ينتظر بيئة جاهزة"}</Text><Text style={[styles.runtimeHeroDetail, { color: colors.muted }]}>{primaryRunner ? `${primaryRunner.label} · آخر نبض ${formatHeartbeat(primaryRunner.lastHeartbeatAt)}` : "اربط Runner محلياً ثم شغّله لتبدأ طلبات التنفيذ المعتمدة."}</Text></View><View style={[styles.runtimeSignal, { backgroundColor: runnerReady ? colors.success : colors.warning }]}><Text style={styles.runtimeSignalText}>{runnerReady ? "حي" : "—"}</Text></View></View><View style={[styles.runtimeMetrics, { backgroundColor: colors.subtle }]}><RuntimeMetric label="جاهز" value={String(stats.readyRunners)} colors={colors} /><RuntimeMetric label="قيد التشغيل" value={String(stats.active)} colors={colors} /><RuntimeMetric label="مكتمل" value={String(stats.completed)} colors={colors} /><RuntimeMetric label="يتطلب انتباهاً" value={String(stats.requiresAttention)} colors={colors} emphasis={stats.requiresAttention > 0} /></View><View accessible accessibilityRole="text" accessibilityLabel={`حالة اتصال Runtime: ${connection.label}. ${connection.detail}`} style={[styles.realtimeState, { backgroundColor: connection.background, borderColor: connection.border }]}><View style={[styles.realtimeDot, { backgroundColor: connection.dot }]} /><View style={styles.realtimeStateCopy}><Text style={styles.realtimeStateLabel}>{connection.label}</Text><Text style={styles.realtimeStateDetail}>{connection.detail}</Text></View></View></View><OperationalHealthPanel health={operationalHealth} colors={colors} onRefresh={onRefreshHealth} />{pendingApprovals.length ? <View style={[styles.pendingPanel, { backgroundColor: "#4A3414", borderColor: "#765724" }]}><View style={styles.pendingPanelHead}><View><Text style={styles.pendingPanelTitle}>قرارات توقف التنفيذ</Text><Text style={styles.pendingPanelCopy}>لن يحجز Runner أي طلب محمي قبل تسجيل قرارك.</Text></View><View style={styles.pendingCount}><Text style={styles.pendingCountText}>{pendingApprovals.length}</Text></View></View>{pendingApprovals.slice(0, 2).map((record) => <RuntimeApprovalAction key={record.approval.id} record={record} resolving={resolving} canResolve={canResolve} onResolve={onResolve} />)}{pendingApprovals.length > 2 ? <Text style={styles.pendingMore}>توجد {pendingApprovals.length - 2} قرارات إضافية في تبويب الموافقات.</Text> : null}</View> : <View style={[styles.clearPanel, { backgroundColor: colors.subtle, borderColor: colors.border }]}><Text style={[styles.clearPanelTitle, { color: colors.foreground }]}>لا توجد موافقات معلقة</Text><Text style={[styles.clearPanelCopy, { color: colors.muted }]}>تستطيع مراجعة السجل؛ سيظهر أي قرار يوقف التنفيذ هنا فور إنشائه.</Text></View>}<View style={styles.logHeader}><Text style={[styles.logHeading, { color: colors.foreground }]}>سجل التنفيذ</Text><Text accessibilityLiveRegion="polite" style={[styles.logCount, { color: colors.muted }]}>{filteredCount} من {totalCount} · {runtimeLogFilterSummary({ status: filter, eventType, severity, search, timeRange })}</Text></View><View style={[styles.filterRow, { backgroundColor: colors.subtle }]}><RuntimeFilterButton active={filter === "all"} label="الكل" onPress={() => setFilter("all")} colors={colors} /><RuntimeFilterButton active={filter === "active"} label="نشط" onPress={() => setFilter("active")} colors={colors} /><RuntimeFilterButton active={filter === "attention"} label="قرار" onPress={() => setFilter("attention")} colors={colors} /><RuntimeFilterButton active={filter === "failed"} label="فشل" onPress={() => setFilter("failed")} colors={colors} /></View><View style={[styles.logFilterPanel, { backgroundColor: colors.surface, borderColor: colors.border }]}><Text style={[styles.logFilterPanelTitle, { color: colors.foreground }]}>بحث ومرشحات محفوظة</Text><TextInput value={search} onChangeText={setSearch} placeholder="ابحث في المسار أو السبب أو المخرجات" placeholderTextColor={colors.muted} textAlign="right" style={[styles.runtimeSearch, { backgroundColor: colors.subtle, borderColor: colors.border, color: colors.foreground }]} /><Text style={[styles.logFilterLabel, { color: colors.muted }]}>النطاق الزمني</Text><View style={styles.filterTagRow}><RuntimeFilterButton compact active={timeRange === "all"} label="كل الوقت" onPress={() => setTimeRange("all")} colors={colors} /><RuntimeFilterButton compact active={timeRange === "24h"} label="آخر 24 ساعة" onPress={() => setTimeRange("24h")} colors={colors} /><RuntimeFilterButton compact active={timeRange === "7d"} label="آخر 7 أيام" onPress={() => setTimeRange("7d")} colors={colors} /></View><Text style={[styles.logFilterLabel, { color: colors.muted }]}>مرشحات جاهزة</Text><View style={styles.filterTagRow}>{runtimeSavedFilters.map((preset) => <RuntimeFilterButton key={preset.id} compact active={runtimeLogFilterSummary({ status: filter, eventType, severity, search, timeRange }) === runtimeLogFilterSummary(preset)} label={preset.label} onPress={() => onApplyPreset(preset)} colors={colors} />)}</View><Text style={[styles.logFilterLabel, { color: colors.muted }]}>نوع الحدث</Text><View style={styles.filterTagRow}><RuntimeFilterButton compact active={eventType === "all"} label="كل الأنواع" onPress={() => setEventType("all")} colors={colors} /><RuntimeFilterButton compact active={eventType === "execution"} label="تنفيذ" onPress={() => setEventType("execution")} colors={colors} /><RuntimeFilterButton compact active={eventType === "approval"} label="موافقة" onPress={() => setEventType("approval")} colors={colors} /><RuntimeFilterButton compact active={eventType === "environment"} label="بيئة" onPress={() => setEventType("environment")} colors={colors} /><RuntimeFilterButton compact active={eventType === "policy"} label="سياسة" onPress={() => setEventType("policy")} colors={colors} /></View><Text style={[styles.logFilterLabel, { color: colors.muted }]}>مستوى الأهمية</Text><View style={styles.filterTagRow}><RuntimeFilterButton compact active={severity === "all"} label="كل المستويات" onPress={() => setSeverity("all")} colors={colors} /><RuntimeFilterButton compact active={severity === "info"} label="معلومة" onPress={() => setSeverity("info")} colors={colors} /><RuntimeFilterButton compact active={severity === "warning"} label="تنبيه" onPress={() => setSeverity("warning")} colors={colors} /><RuntimeFilterButton compact active={severity === "critical"} label="حرج" onPress={() => setSeverity("critical")} colors={colors} /></View><Pressable onPress={onExport} style={({ pressed }) => [styles.exportButton, { backgroundColor: colors.subtle, borderColor: colors.primary }, pressed && styles.pressed]}><Text style={[styles.exportButtonText, { color: colors.primary }]}>تصدير السجل المنقح ({filteredCount})</Text></Pressable></View></View>;
}

function RuntimeMetric({ label, value, colors, emphasis = false }: { label: string; value: string; colors: ReturnType<typeof useColors>; emphasis?: boolean }) { return <View style={styles.runtimeMetric}><Text style={[styles.runtimeMetricValue, { color: emphasis ? colors.warning : colors.foreground }]}>{value}</Text><Text style={[styles.runtimeMetricLabel, { color: colors.muted }]}>{label}</Text></View>; }

function OperationalHealthPanel({ health, colors, onRefresh }: { health: ReturnType<typeof getOperationalHealth>; colors: ReturnType<typeof useColors>; onRefresh: () => void }) { const toneColor = health.tone === "critical" ? colors.error : health.tone === "warning" ? colors.warning : colors.success; return <View style={[styles.healthPanel, { backgroundColor: colors.surface, borderColor: toneColor }]}><View style={styles.healthHeader}><View><Text style={[styles.healthTitle, { color: colors.foreground }]}>ملخص صحة اليوم</Text><Text style={[styles.healthCopy, { color: colors.muted }]}>{health.label} · يتحدث عند فتح الشاشة أو طلب التحديث.</Text></View><Text style={[styles.healthState, { color: toneColor }]}>{health.workerFresh ? "العامل حي" : "تحقق من العامل"}</Text></View><View style={[styles.healthGrid, { backgroundColor: colors.subtle }]}>{health.cards.map((card) => <View key={card.id} style={styles.healthMetric}><Text style={[styles.healthMetricValue, { color: card.tone === "critical" ? colors.error : card.tone === "warning" ? colors.warning : colors.foreground }]}>{card.value}</Text><Text style={[styles.healthMetricLabel, { color: colors.muted }]}>{card.label}</Text></View>)}</View><Pressable onPress={onRefresh} style={({ pressed }) => [styles.healthRefresh, { borderColor: colors.primary }, pressed && styles.pressed]}><Text style={[styles.healthRefreshText, { color: colors.primary }]}>تحديث ملخص اليوم</Text></Pressable><Text style={[styles.healthRetention, { color: colors.muted }]}>يُحتفظ بمخرجات Runtime المقتطعة لمدة {runtimeRetentionPolicy.runtimeLogRetentionDays} يوماً؛ والتصدير يحجب القيم الحساسة ويقص المخرجات.</Text></View>; }

function RuntimeFilterButton({ active, label, onPress, colors, compact = false }: { active: boolean; label: string; onPress: () => void; colors: ReturnType<typeof useColors>; compact?: boolean }) { return <Pressable accessibilityRole="button" accessibilityState={{ selected: active }} onPress={onPress} style={({ pressed }) => [compact ? styles.filterTagButton : styles.filterButton, active && { backgroundColor: colors.elevated }, pressed && styles.pressed]}><Text style={[styles.filterText, { color: active ? colors.primary : colors.muted }]}>{label}</Text></Pressable>; }

function RuntimeApprovalAction({ record, resolving, canResolve, onResolve }: { record: ApprovalInboxEntry; resolving: boolean; canResolve: boolean; onResolve: (record: ApprovalInboxEntry, decision: "approved" | "rejected") => void }) { const blocked = resolving || !canResolve; return <View style={styles.runtimeApproval}><View style={styles.runtimeApprovalTitleRow}><Text style={styles.runtimeApprovalTitle}>{record.approval.title}</Text><Text style={styles.runtimeApprovalLevel}>{record.approval.level.toUpperCase()}</Text></View><Text style={styles.runtimeApprovalProject}>{record.project.code} · {record.approval.impact}</Text><View style={styles.actions}><Pressable disabled={blocked} onPress={() => onResolve(record, "rejected")} accessibilityRole="button" accessibilityLabel="رفض القرار" style={({ pressed }) => [styles.rejectButton, { backgroundColor: "#4A202A" }, (pressed || blocked) && styles.pressed]}><Text style={styles.rejectText}>رفض</Text></Pressable><Pressable disabled={blocked} onPress={() => onResolve(record, "approved")} accessibilityRole="button" accessibilityLabel="اعتماد التنفيذ" style={({ pressed }) => [styles.approveButton, { backgroundColor: "#FFFFFF" }, (pressed || blocked) && styles.pressed]}><Text style={styles.runtimeApproveText}>{resolving ? "جارٍ التسجيل…" : canResolve ? "اعتماد التنفيذ" : "يتطلب اتصالاً"}</Text></Pressable></View></View>; }

function BudgetSummary({ spent, remaining, percent, budgetLimit, colors }: { spent: number; remaining: number; percent: number; budgetLimit: number; colors: ReturnType<typeof useColors> }) { const alert = percent >= 85; return <View style={[styles.budgetCard, { backgroundColor: colors.surface, borderColor: alert ? colors.warning : colors.border }]}><View style={styles.budgetTop}><View><Text style={[styles.budgetLabel, { color: colors.muted }]}>استهلاك المشروع</Text><Text style={[styles.budgetValue, { color: colors.foreground }]}>${spent.toFixed(2)} <Text style={[styles.budgetUnit, { color: colors.muted }]}>من ${budgetLimit.toFixed(2)}</Text></Text></View><StatusPill label={alert ? "قريب من الحد" : "ضمن الحد"} tone={alert ? "warning" : "success"} /></View><View style={[styles.track, { backgroundColor: colors.subtle }]}><View style={[styles.fill, { width: `${percent}%`, backgroundColor: alert ? colors.warning : colors.primary }]} /></View><View style={styles.budgetBottom}><Text style={[styles.budgetHint, { color: colors.muted }]}>متبقي ${remaining.toFixed(2)}$ قبل سقف الميزانية</Text><Text style={[styles.budgetPercent, { color: colors.primary }]}>{percent}%</Text></View></View>; }

function ApprovalSummary({ pendingCount, colors }: { pendingCount: number; colors: ReturnType<typeof useColors> }) { return <View style={[styles.approvalSummary, { backgroundColor: "#4A3414", borderColor: "#765724" }]}><View style={[styles.summaryNumber, { backgroundColor: colors.warning }]}><Text style={styles.summaryNumberText}>{pendingCount}</Text></View><View style={styles.summaryBody}><Text style={styles.summaryTitle}>قرارات متصلة بسير العمل</Text><Text style={styles.summaryCopy}>يعتمد القرار هنا تحديث طلب الموافقة ومسار Task Engine المرتبط به.</Text></View></View>; }

function CostRow({ entry, colors }: { entry: CostEntry; colors: ReturnType<typeof useColors> }) { return <View style={[styles.card, { backgroundColor: colors.surface, borderColor: colors.border }]}><View style={styles.costTop}><View><Text style={[styles.rowTitle, { color: colors.foreground }]}>{entry.task}</Text><Text style={[styles.rowSubtitle, { color: colors.muted }]}>{entry.agent}</Text></View><Text style={[styles.costValue, { color: colors.primary }]}>${entry.cost.toFixed(2)}</Text></View><View style={[styles.metricStrip, { backgroundColor: colors.subtle }]}><Metric label="النموذج" value={entry.model} colors={colors} /><Metric label="الرموز" value={formatTokens(entry.tokens)} colors={colors} /><Metric label="المدة" value={entry.duration} colors={colors} /></View></View>; }
function Metric({ label, value, colors }: { label: string; value: string; colors: ReturnType<typeof useColors> }) { return <View style={styles.metric}><Text style={[styles.metricValue, { color: colors.foreground }]}>{value}</Text><Text style={[styles.metricLabel, { color: colors.muted }]}>{label}</Text></View>; }

function ApprovalRow({ record, colors, resolving, canResolve, onResolve }: { record: ApprovalInboxEntry; colors: ReturnType<typeof useColors>; resolving: boolean; canResolve: boolean; onResolve: (decision: "approved" | "rejected") => void }) { const { approval, project, engineStep, engineRun, sensitiveChange } = record; const pending = approval.status === "pending"; const blocked = resolving || !canResolve; const levelColor = approval.level === "approval" ? colors.error : approval.level === "review" ? colors.warning : colors.success; const context = engineStep ? `الخطوة ${engineStep.stepOrder}: ${engineStep.title}` : "طلب مستقل خارج Task Engine"; const engineState = engineRun ? `دورة Task Engine #${engineRun.id} · ${engineStatusLabel(engineRun.status)}` : "لا توجد دورة محرك مرتبطة"; return <View style={[styles.card, { backgroundColor: colors.surface, borderColor: colors.border }]}><View style={styles.approvalTop}><View style={styles.approvalHeading}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{approval.title}</Text><Text style={[styles.rowSubtitle, { color: colors.muted }]}>{project.code} · {project.name} · {approval.requestedBy}</Text></View><StatusPill label={approvalStatusLabel(approval.status)} tone={approvalTone(approval.status)} /></View><Text style={[styles.requestDetail, { color: colors.muted }]}>{approval.detail}</Text><View style={[styles.contextBox, { backgroundColor: colors.subtle }]}><Text style={[styles.contextTitle, { color: colors.primary }]}>{context}</Text><Text style={[styles.contextCopy, { color: colors.muted }]}>{engineState}</Text></View>{sensitiveChange ? <View style={styles.secondaryBox}><View style={styles.secondaryTop}><Text style={styles.secondaryBadge}>مراجعة ثانوية</Text><Text style={styles.secondaryPath}>{sensitiveChange.path}</Text></View><Text style={styles.secondaryRisk}>الإشارات: {sensitiveChange.riskSummary}</Text><Text style={styles.secondaryState}>{secondaryChangeStatus(sensitiveChange.status, approval.status, sensitiveChange.baseVersion)}</Text></View> : null}<View style={[styles.levelBox, { backgroundColor: colors.subtle }]}><Text style={[styles.levelBadge, { color: levelColor }]}>{approval.level.toUpperCase()}</Text><Text style={[styles.levelText, { color: colors.foreground }]}>{approval.impact}</Text></View>{pending ? <View style={styles.actions}><Pressable disabled={blocked} onPress={() => onResolve("rejected")} accessibilityRole="button" accessibilityLabel="رفض الموافقة" style={({ pressed }) => [styles.rejectButton, { backgroundColor: "#4A202A" }, (pressed || blocked) && styles.pressed]}><Text style={styles.rejectText}>رفض</Text></Pressable><Pressable disabled={blocked} onPress={() => onResolve("approved")} accessibilityRole="button" accessibilityLabel="اعتماد الموافقة" style={({ pressed }) => [styles.approveButton, { backgroundColor: colors.primary }, (pressed || blocked) && styles.pressed]}><Text style={styles.approveText}>{resolving ? "جارٍ تسجيل القرار…" : canResolve ? "اعتماد" : "يتطلب اتصالاً"}</Text></Pressable></View> : <Text style={[styles.resolved, { color: colors.muted }]}>{sensitiveChange ? secondaryResolvedText(sensitiveChange.status) : approval.status === "approved" ? "اعتمد القرار؛ سيستأنف Task Engine الخطوة أو يكملها منطقياً." : approval.status === "rejected" ? "رُفض القرار؛ تُحجب دورة Task Engine المرتبطة ولا تنفذ أدوات." : "سُجل الإجراء تلقائياً ضمن السياسة."}</Text>}</View>; }

function RuntimeRow({ record, colors }: { record: RuntimeLogEntry; colors: ReturnType<typeof useColors> }) { const { request, project, runner } = record; const hasOutput = Boolean(request.stdout?.trim() || request.stderr?.trim()); const eventType = getRuntimeEventType(request.status); const severity = getRuntimeSeverity(request.status); return <View style={[styles.card, { backgroundColor: colors.surface, borderColor: runtimeBorder(request.status, colors) }]}><View style={styles.approvalTop}><View style={styles.approvalHeading}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{request.targetPath}</Text><Text style={[styles.rowSubtitle, { color: colors.muted }]}>{project.code} · {project.name} · {runner?.label ?? "Runner غير محدد"} · {formatRuntimeTime(request.completedAt ?? request.createdAt)}</Text></View><StatusPill label={runtimeStatusLabel(request.status)} tone={runtimeTone(request.status)} /></View><View style={styles.runtimeClassification}><Text style={[styles.runtimeClassificationType, { color: colors.primary }]}>نوع: {runtimeEventTypeLabel(eventType)}</Text><Text style={[styles.runtimeClassificationSeverity, { color: runtimeSeverityColor(severity, colors) }]}>الأهمية: {runtimeSeverityLabel(severity)}</Text></View><View style={[styles.metricStrip, { backgroundColor: colors.subtle }]}><Metric label="الملف" value={request.profile === "typescript_lockfile" ? "TypeScript" : "JavaScript"} colors={colors} /><Metric label="المدة" value={request.durationMs === null ? "—" : `${request.durationMs}ms`} colors={colors} /><Metric label="الخروج" value={request.exitCode === null ? "—" : String(request.exitCode)} colors={colors} /></View><Text style={[styles.requestDetail, { color: colors.muted }]}>{request.reason}</Text>{hasOutput ? <View style={[styles.runtimeOutput, { backgroundColor: colors.subtle, borderColor: colors.border }]}>{request.stdout?.trim() ? <><Text style={[styles.outputLabel, { color: colors.primary }]}>stdout</Text><Text selectable style={[styles.outputText, { color: colors.foreground }]}>{request.stdout}</Text></> : null}{request.stderr?.trim() ? <><Text style={[styles.outputLabel, { color: colors.error }]}>stderr</Text><Text selectable style={[styles.outputText, { color: colors.error }]}>{request.stderr}</Text></> : null}</View> : <Text style={[styles.noOutput, { color: colors.muted }]}>لا توجد مخرجات بعد؛ ستظهر نتيجة Runner المقتطعة فور اكتمال الطلب.</Text>}</View>; }

function EmptyApprovals({ loading, error, colors }: { loading: boolean; error: boolean; colors: ReturnType<typeof useColors> }) { return <View style={[styles.emptyCard, { backgroundColor: colors.surface, borderColor: colors.border }]}><Text style={[styles.emptyTitle, { color: colors.foreground }]}>{loading ? "جارٍ تحميل الموافقات…" : error ? "تعذر تحميل صندوق الموافقات" : "لا توجد قرارات معلقة"}</Text><Text style={[styles.emptyCopy, { color: colors.muted }]}>{error ? "تحقق من الاتصال ثم أعد فتح الشاشة." : "ستظهر بوابات REVIEW وAPPROVAL التي ينشئها Task Engine هنا."}</Text></View>; }
function EmptyRuntime({ loading, error, filters, colors }: { loading: boolean; error: boolean; filters: { status: RuntimeFilter; eventType: RuntimeEventType; severity: RuntimeSeverity; search?: string; timeRange?: RuntimeTimeRange }; colors: ReturnType<typeof useColors> }) { const filterCopy = filters.status === "all" && filters.eventType === "all" && filters.severity === "all" && !filters.search && (filters.timeRange ?? "all") === "all" ? "بعد ربط Runner محلي واعتماد طلب تنفيذ، ستظهر النتيجة والمخرجات هنا." : `لا توجد سجلات ضمن المرشحات الحالية: ${runtimeLogFilterSummary(filters)}.`; return <View style={[styles.emptyCard, { backgroundColor: colors.surface, borderColor: colors.border }]}><Text style={[styles.emptyTitle, { color: colors.foreground }]}>{loading ? "جارٍ تحميل سجل Runtime…" : error ? "تعذر تحميل سجل Runtime" : "لا توجد نتائج مطابقة"}</Text><Text style={[styles.emptyCopy, { color: colors.muted }]}>{error ? "تحقق من الاتصال ثم أعد فتح الشاشة." : filterCopy}</Text></View>; }
function ApprovalFootnote({ colors }: { colors: ReturnType<typeof useColors> }) { return <View style={[styles.footnote, { backgroundColor: colors.subtle }]}><Text style={[styles.footnoteTitle, { color: colors.primary }]}>تأثير القرار</Text><Text style={[styles.footnoteCopy, { color: colors.muted }]}>الاعتماد أو الرفض يحدّث الطلب أولاً، ثم يدفع Task Engine لاستئناف الخطوة أو حجب الدورة مع سجل أحداث دائم.</Text></View>; }
function RuntimeFootnote({ colors }: { colors: ReturnType<typeof useColors> }) { return <View style={[styles.footnote, { backgroundColor: colors.subtle }]}><Text style={[styles.footnoteTitle, { color: colors.primary }]}>حدود سجل Runtime</Text><Text style={[styles.footnoteCopy, { color: colors.muted }]}>لا ينفذ Runner سوى ملف واحد معتمد داخل حاوية بلا شبكة. تُقتطع stdout وstderr لحماية قاعدة البيانات، ولا تُرسل متغيرات بيئة الجهاز.</Text></View>; }

function approvalStatusLabel(status: "pending" | "approved" | "rejected" | "auto_resolved") { return status === "pending" ? "بانتظار قرار" : status === "approved" ? "معتمد" : status === "rejected" ? "مرفوض" : "تلقائي"; }
function approvalTone(status: "pending" | "approved" | "rejected" | "auto_resolved") { return status === "pending" ? "warning" : status === "approved" || status === "auto_resolved" ? "success" : "error" as const; }
function runtimeStatusLabel(status: string) { return status === "awaiting_approval" ? "بانتظار موافقة" : status === "queued" ? "في الطابور" : status === "claimed" ? "قيد التنفيذ" : status === "completed" ? "مكتمل" : status === "failed" ? "فشل" : status === "environment_required" ? "Runner مطلوب" : status === "blocked" ? "محجوب" : status === "cancelled" ? "ملغى" : status; }
function runtimeTone(status: string) { return status === "completed" ? "success" : status === "failed" || status === "blocked" ? "error" : status === "awaiting_approval" || status === "environment_required" ? "warning" : "muted" as const; }
function runtimeBorder(status: string, colors: ReturnType<typeof useColors>) { return status === "failed" || status === "blocked" ? colors.error : status === "awaiting_approval" || status === "environment_required" ? colors.warning : colors.border; }
function runtimeFilterLabel(filter: RuntimeFilter) { return filter === "all" ? "كل السجلات" : filter === "active" ? "عمليات نشطة" : filter === "attention" ? "تحتاج قراراً" : "فشلت أو حُجبت"; }
function runtimeEventTypeLabel(eventType: Exclude<RuntimeEventType, "all">) { return eventType === "approval" ? "موافقة" : eventType === "environment" ? "بيئة" : eventType === "policy" ? "سياسة" : "تنفيذ"; }
function runtimeSeverityLabel(severity: Exclude<RuntimeSeverity, "all">) { return severity === "critical" ? "حرج" : severity === "warning" ? "تنبيه" : "معلومة"; }
function runtimeSeverityColor(severity: Exclude<RuntimeSeverity, "all">, colors: ReturnType<typeof useColors>) { return severity === "critical" ? colors.error : severity === "warning" ? colors.warning : colors.success; }
function runtimeLogFilterSummary(filters: { status: RuntimeFilter; eventType: RuntimeEventType; severity: RuntimeSeverity; search?: string; timeRange?: RuntimeTimeRange }) { const parts = [filters.status !== "all" ? runtimeFilterLabel(filters.status) : null, filters.eventType !== "all" ? `نوع ${runtimeEventTypeLabel(filters.eventType)}` : null, filters.severity !== "all" ? `أهمية ${runtimeSeverityLabel(filters.severity)}` : null, filters.search?.trim() ? `بحث ${filters.search.trim()}` : null, filters.timeRange === "24h" ? "آخر 24 ساعة" : filters.timeRange === "7d" ? "آخر 7 أيام" : null].filter(Boolean); return parts.length ? parts.join(" · ") : "كل السجلات"; }
function formatHeartbeat(value: Date | null) { return value ? formatRuntimeTime(value) : "لم يصل heartbeat بعد"; }
function formatRuntimeTime(value: Date) { const date = new Date(value); return Number.isNaN(date.getTime()) ? "وقت غير متاح" : date.toLocaleString("ar", { day: "numeric", hour: "2-digit", minute: "2-digit", month: "short" }); }
function secondaryChangeStatus(status: "pending_secondary" | "applied" | "rejected" | "conflicted", approvalStatus: "pending" | "approved" | "rejected" | "auto_resolved", baseVersion: number) { return status === "pending_secondary" ? `بانتظار القرار · سيطبق فقط إذا بقي الملف عند الإصدار ${baseVersion}` : status === "applied" ? "طُبق الاقتراح بعد التحقق من الإصدار" : status === "conflicted" ? "تعارض الإصدار — لم يكتب النظام فوق الملف الأحدث" : approvalStatus === "rejected" ? "رُفض الاقتراح ولم يتغير الملف" : "تمت معالجة الاقتراح"; }
function secondaryResolvedText(status: "pending_secondary" | "applied" | "rejected" | "conflicted") { return status === "applied" ? "اعتمدت المراجعة الثانوية وطُبق التعديل بعد التحقق من إصدار الملف." : status === "conflicted" ? "اعتمدت المراجعة، لكن إصدار الملف تغير؛ لم يكتب النظام فوق التغيير الأحدث." : status === "rejected" ? "رُفض التعديل الحساس وبقي الملف دون تغيير." : "المراجعة الثانوية ما زالت بانتظار القرار."; }
function engineStatusLabel(status: "queued" | "running" | "awaiting_review" | "awaiting_approval" | "verifying" | "completed" | "failed" | "blocked") { return status === "awaiting_review" ? "بانتظار مراجعة" : status === "awaiting_approval" ? "بانتظار موافقة" : status === "completed" ? "مكتملة" : status === "blocked" ? "محجوبة" : status === "failed" ? "فشلت" : status === "running" ? "قيد المعالجة" : status === "verifying" ? "قيد التحقق" : "في الانتظار"; }
function formatTokens(tokens: number) { return `${(tokens / 1000).toFixed(1)}k`; }

